Text:
{({a}) => {
  const fmt = (x) => { const n = Math.round(x * 100) / 100; return Object.is(n, -0) ? "0" : String(n); };
  const M = (s) => "$$\n" + s + "\n$$";
  if (Math.abs(a) < 0.05) return "При $a = 0$ функция не квадратичная.";
  const xv = 2 / (2 * a), yv = a * xv * xv - 2 * xv - 3;
  return [
    "Функция:", M("y = " + fmt(a) + "x^2 - 2x - 3"),
    "Ветви направлены **" + (a > 0 ? "вверх" : "вниз") + "**, в вершине " + (a > 0 ? "минимум" : "максимум") + ":",
    M(a > 0 ? "E(f) = [" + fmt(yv) + ";\\ +\\infty)" : "E(f) = (-\\infty;\\ " + fmt(yv) + "]")
  ].join("\n\n");
}}
